2	new file mode 100644
3	index 00000000..78718d48
4	--- /dev/null
5	+++ b/cmd/entire/cli/plugin_fetch.go
6	@@ -0,0 +1,617 @@
7	+package cli
8	+
9	+import (
10	+	"archive/tar"
11	+	"archive/zip"
12	+	"compress/gzip"
13	+	"context"
14	+	"crypto/sha256"
15	+	"encoding/hex"
16	+	"errors"
17	+	"fmt"
18	+	"io"
19	+	"net"
20	+	"net/http"
21	+	"net/url"
22	+	"os"
23	+	"path"
24	+	"path/filepath"
25	+	"runtime"
26	+	"strings"
27	+	"time"
28	+)
29	+
30	+// Release-asset download. The one irreducibly forge-specific piece of the
31	+// plugin system is where release binaries live; it's contained here as a
32	+// small per-host URL convention table with a declarative escape hatch
33	+// (download_url in entire-plugin.yml). Everything else — version listing,
34	+// metadata, the index — runs on the git protocol.
35	+
36	+// errAssetNotFound distinguishes "this tag has no matching asset" (worth
37	+// trying the next-highest tag — a pushed tag whose release isn't published
38	+// yet) from transport errors (not worth retrying on another tag).
39	+var errAssetNotFound = errors.New("no matching release asset")
40	+
41	+// errUnverifiedAsset means an asset was reachable but nothing authenticated
42	+// it — no checksums.txt covering this platform. Distinct from
43	+// errAssetNotFound so it never triggers the next-highest-tag walk: falling
44	+// back to an older tag wouldn't make the download any more trustworthy.
45	+var errUnverifiedAsset = errors.New("release asset cannot be verified")
46	+
47	+// requireSecureAssetURL gates every plugin HTTP fetch on a transport that a
48	+// network attacker can't rewrite.
49	+//
50	+// Plaintext HTTP is not merely "less good" here: the asset and the
51	+// checksums.txt that authenticates it come from the same origin, so an
52	+// attacker who can rewrite one can rewrite both, and checksum verification
53	+// becomes theatre. HTTPS is therefore required for anything off-machine.
54	+//
55	+// Loopback is exempt so httptest-backed tests and local forge experiments
56	+// keep working — traffic that never leaves the machine has no network
57	+// attacker to defend against.
58	+func requireSecureAssetURL(rawURL string) error {
59	+	u, err := url.Parse(rawURL)
60	+	if err != nil {
61	+		return fmt.Errorf("parse download URL %q: %w", redactURL(rawURL), err)
62	+	}
63	+	switch strings.ToLower(u.Scheme) {
64	+	case "https":
65	+		return nil
66	+	case "http":
67	+		if isLoopbackHost(u.Hostname()) {
68	+			return nil
69	+		}
70	+		return fmt.Errorf("refusing to download %s over plaintext HTTP: the asset and its %s would share an origin, so a network attacker could replace both and checksum verification would prove nothing; serve the release over HTTPS or declare an https download_url in %s",
71	+			redactURL(rawURL), checksumsFileName, pluginMetadataFileName)
72	+	default:
73	+		return fmt.Errorf("plugin downloads must use https; %q has scheme %q", redactURL(rawURL), u.Scheme)
74	+	}
75	+}
76	+
77	+// isLoopbackHost reports whether host addresses this machine.
78	+func isLoopbackHost(host string) bool {
79	+	if strings.EqualFold(host, "localhost") {
80	+		return true
81	+	}
82	+	if ip := net.ParseIP(host); ip != nil {
83	+		return ip.IsLoopback()
84	+	}
85	+	return false
86	+}
87	+
88	+// maxAssetRedirects bounds the redirect chain for an asset fetch. Release
89	+// hosts routinely redirect to a CDN, so some hops are expected.
90	+const maxAssetRedirects = 10
91	+
92	+// pluginHTTPClient bounds the total time for a single asset download.
93	+// Plugins can be tens of MB; 5 minutes is generous even on slow links.
94	+//
95	+// CheckRedirect re-runs the transport check on every hop. Without it the
96	+// https-only rule is trivially bypassed: Go's default policy follows up to 10
97	+// redirects *across schemes* and only the initial URL was ever validated, so an
98	+// https:// entry point could deliver both the asset and its checksums.txt over
99	+// plaintext — exactly the outcome requireSecureAssetURL exists to prevent.
100	+var pluginHTTPClient = &http.Client{
101	+	Timeout: 5 * time.Minute,
102	+	CheckRedirect: func(req *http.Request, via []*http.Request) error {
103	+		if len(via) >= maxAssetRedirects {
104	+			return fmt.Errorf("stopped after %d redirects", maxAssetRedirects)
105	+		}
106	+		return requireSecureAssetURL(req.URL.String())
107	+	},
108	+}
109	+
110	+// maxPluginAssetSize caps a downloaded asset. Real plugin binaries are tens
111	+// of MB; the cap exists so a misconfigured URL serving an endless stream
112	+// can't fill the disk.
113	+const maxPluginAssetSize = 512 << 20 // 512 MiB
114	+
115	+// releaseAssetBaseURL returns the URL prefix release assets live under for
116	+// the repo's host. GitHub and the Gitea family share a convention; GitLab
117	+// has its own. Unknown hosts default to the GitHub-style convention (most
118	+// self-hosted forges mirror it) — authors on hosts that don't can declare
119	+// download_url in entire-plugin.yml.
120	+func releaseAssetBaseURL(repoURL, tag string) (string, error) {
121	+	u, err := url.Parse(strings.TrimSuffix(repoURL, ".git"))
122	+	if err != nil {
123	+		return "", fmt.Errorf("parse repo URL: %w", err)
124	+	}
125	+	if u.Scheme != "https" && u.Scheme != "http" {
126	+		return "", fmt.Errorf("release downloads need an http(s) repo URL, got %q (declare download_url in %s for non-HTTP remotes)", redactURL(repoURL), pluginMetadataFileName)
127	+	}
128	+	base := strings.TrimSuffix(u.String(), "/")
129	+	host := strings.ToLower(u.Hostname())
130	+	if host == "gitlab.com" || strings.HasPrefix(host, "gitlab.") {
131	+		return base + "/-/releases/" + url.PathEscape(tag) + "/downloads/", nil
132	+	}
133	+	return base + "/releases/download/" + url.PathEscape(tag) + "/", nil
134	+}
135	+
136	+// expandDownloadTemplate expands the author-declared download_url template.
137	+// Placeholders: {name} {tag} {version} {os} {arch} {asset}.
138	+func expandDownloadTemplate(tmpl, name, tag, asset string) string {
139	+	r := strings.NewReplacer(
140	+		"{name}", name,
141	+		"{tag}", tag,
142	+		"{version}", strings.TrimPrefix(tag, "v"),
143	+		"{os}", runtime.GOOS,
144	+		"{arch}", runtime.GOARCH,
145	+		"{asset}", asset,
146	+	)
147	+	return r.Replace(tmpl)
148	+}
149	+
150	+// archAliases maps a GOARCH to the spellings seen in release asset names.
151	+func archAliases(goarch string) []string {
152	+	switch goarch {
153	+	case "amd64":
154	+		return []string{"amd64", "x86_64"}
155	+	case "arm64":
156	+		return []string{"arm64", "aarch64"}
157	+	default:
158	+		return []string{goarch}
159	+	}
160	+}
161	+
162	+// osAliases maps a GOOS to asset-name spellings, most specific first.
163	+func osAliases(goos string) []string {
164	+	if goos == darwinGOOS {
165	+		return []string{"darwin", "macos"}
166	+	}
167	+	return []string{goos}
168	+}
169	+
170	+// platformArchAliases returns the arch spellings to try for goos. On darwin it
171	+// appends "all", which is where goreleaser puts the universal-binary marker:
172	+// the name is entire-<x>_<ver>_darwin_all, so "all" belongs in the arch slot.
173	+// It used to sit in the OS slot, generating _all_arm64 — a spelling no forge
174	+// produces — so the darwin_all fallback the docs promise never actually
175	+// matched and universal-only releases could not be installed at all.
176	+func platformArchAliases(goos, goarch string) []string {
177	+	aliases := archAliases(goarch)
178	+	if goos == darwinGOOS {
179	+		aliases = append(aliases, "all")
180	+	}
181	+	return aliases
182	+}
183	+
184	+// assetCandidates returns release asset filenames to try for this platform,
185	+// in preference order: archives before raw binaries, version-in-name
186	+// (goreleaser's default template) before version-less.
187	+func assetCandidates(name, tag string) []string {
188	+	binName := pluginBinaryPrefix + name
189	+	version := strings.TrimPrefix(tag, "v")
190	+	stems := make([]string, 0, 16)
191	+	for _, osName := range osAliases(runtime.GOOS) {
192	+		for _, arch := range platformArchAliases(runtime.GOOS, runtime.GOARCH) {
193	+			stems = append(stems,
194	+				fmt.Sprintf("%s_%s_%s_%s", binName, version, osName, arch),
195	+				fmt.Sprintf("%s_%s_%s", binName, osName, arch),
196	+			)
197	+		}
198	+	}
199	+	exts := []string{".tar.gz", ".zip", ""}
200	+	if runtime.GOOS == windowsGOOS {
201	+		exts = []string{".zip", ".tar.gz", windowsExeExt}
202	+	}
203	+	var out []string
204	+	for _, ext := range exts {
205	+		for _, stem := range stems {
206	+			out = append(out, stem+ext)
207	+		}
208	+	}
209	+	return out
210	+}
211	+
212	+// checksumsFileName is the conventional name of a release's checksum
213	+// manifest (goreleaser's default).
214	+const checksumsFileName = "checksums.txt"
215	+
216	+// checksumCandidates returns filenames the checksum manifest may go by.
217	+func checksumCandidates(name, tag string) []string {
218	+	binName := pluginBinaryPrefix + name
219	+	version := strings.TrimPrefix(tag, "v")
220	+	return []string{
221	+		checksumsFileName,
222	+		fmt.Sprintf("%s_%s_checksums.txt", binName, version),
223	+		binName + "_checksums.txt",
224	+	}
225	+}
226	+
227	+// parseChecksums parses "hex  filename" lines (sha256sum format) into a
228	+// filename → digest map.
229	+func parseChecksums(data []byte) map[string]string {
230	+	out := make(map[string]string)
231	+	for _, line := range strings.Split(string(data), "\n") {
232	+		fields := strings.Fields(line)
233	+		if len(fields) != 2 {
234	+			continue
235	+		}
236	+		// sha256sum marks binary-mode files with a leading *.
237	+		out[strings.TrimPrefix(fields[1], "*")] = strings.ToLower(fields[0])
238	+	}
239	+	return out
240	+}
241	+
242	+// selectAssetFromChecksums picks the preferred candidate present in the
243	+// checksum manifest. The manifest lists what was actually published, so
244	+// this avoids probing candidate URLs one by one.
245	+func selectAssetFromChecksums(sums map[string]string, name, tag string) (asset, digest string, ok bool) {
246	+	for _, c := range assetCandidates(name, tag) {
247	+		if d, present := sums[c]; present {
248	+			return c, d, true
249	+		}
250	+	}
251	+	return "", "", false
252	+}
253	+
254	+// fetchedAsset is the result of downloadPluginAsset: a verified asset on
255	+// disk in a caller-owned staging dir.
256	+type fetchedAsset struct {
257	+	// Path is the downloaded asset file inside the staging dir.
258	+	Path string
259	+	// Asset is the asset filename that matched.
260	+	Asset string
261	+	// SHA256 is the hex digest of the downloaded bytes.
262	+	SHA256 string
263	+	// Verified is true when SHA256 was checked against a digest published in
264	+	// the release's checksum manifest, rather than merely computed from
265	+	// whatever arrived. Recorded in the install manifest so `plugin doctor`
266	+	// can surface unverified installs.
267	+	Verified bool
268	+}
269	+
270	+// downloadPluginAsset locates and downloads the release asset for name@tag
271	+// into stagingDir, verifying against the release's checksum manifest when
272	+// one is published. Returns errAssetNotFound (possibly wrapped) when the
273	+// tag has no asset for this platform.
274	+func downloadPluginAsset(ctx context.Context, meta *PluginMetadata, repoURL, name, tag, stagingDir string, allowUnverified bool) (*fetchedAsset, error) {
275	+	// Resolve the prefix once. It does not depend on the asset name, so
276	+	// deriving it per candidate meant re-parsing the repo URL ~36 times in the
277	+	// probe loop and carrying an error return through three call sites for a
278	+	// failure that can only happen here.
279	+	var assetURL func(asset string) string
280	+	if meta != nil && meta.DownloadURL != "" {
281	+		assetURL = func(asset string) string {
282	+			return expandDownloadTemplate(meta.DownloadURL, name, tag, asset)
283	+		}
284	+	} else {
285	+		base, err := releaseAssetBaseURL(repoURL, tag)
286	+		if err != nil {
287	+			return nil, err
288	+		}
289	+		assetURL = func(asset string) string { return base + asset }
290	+	}
291	+
292	+	// A download_url template without {asset} is a single fully-specified
293	+	// URL; there is nothing to select — and no way to locate a checksum
294	+	// manifest, since every candidate name would expand to the same URL.
295	+	if meta != nil && meta.DownloadURL != "" && !strings.Contains(meta.DownloadURL, "{asset}") {
296	+		if !allowUnverified {
297	+			return nil, fmt.Errorf("%w: %s declares a fixed download_url with no {asset} placeholder, so no %s can be located; add {asset} to the template or install with --allow-unverified",
298	+				errUnverifiedAsset, pluginMetadataFileName, checksumsFileName)
299	+		}
300	+		u := expandDownloadTemplate(meta.DownloadURL, name, tag, "")
301	+		return fetchAndVerify(ctx, u, assetNameFromURL(u), "", stagingDir)
302	+	}
303	+
304	+	// Preferred path: fetch the checksum manifest and pick from what was
305	+	// actually published.
306	+	for _, cs := range checksumCandidates(name, tag) {
307	+		data, err := httpGetSmall(ctx, assetURL(cs))
308	+		if err != nil {
309	+			continue
310	+		}
311	+		asset, digest, ok := selectAssetFromChecksums(parseChecksums(data), name, tag)
312	+		if !ok {
313	+			// This manifest lists nothing for the platform. Keep going: a
314	+			// stale or hand-written root checksums.txt must not mask a
315	+			// goreleaser manifest under another candidate name, or a
316	+			// published asset still reachable by the probe fallback.
317	+			// Falling through doesn't weaken verification — an attacker
318	+			// who controls the manifest could list a malicious digest
319	+			// directly.
320	+			continue
321	+		}
322	+		return fetchAndVerify(ctx, assetURL(asset), asset, digest, stagingDir)
323	+	}
324	+
325	+	// Fallback: probe candidates directly (a release published without a
326	+	// checksum manifest). Nothing authenticates these bytes, so by default an
327	+	// asset found this way is refused rather than installed.
328	+	//
329	+	// The probe still runs when verification is required: it distinguishes
330	+	// "this tag has no release yet" (errAssetNotFound, worth walking down to
331	+	// the next tag) from "the release exists but publishes no checksums"
332	+	// (errUnverifiedAsset, which an older tag wouldn't fix). Getting that
333	+	// wrong would report a missing release for a plugin that simply doesn't
334	+	// ship checksums.
335	+	for _, asset := range assetCandidates(name, tag) {
336	+		fa, err := fetchAndVerify(ctx, assetURL(asset), asset, "", stagingDir)
337	+		switch {
338	+		case errors.Is(err, errAssetNotFound):
339	+			continue
340	+		case err != nil:
341	+			return nil, err
342	+		case allowUnverified:
343	+			return fa, nil
344	+		}
345	+		_ = os.Remove(fa.Path)
346	+		return nil, fmt.Errorf("%w: %s %s publishes %s but no %s to authenticate it; ask the author to publish checksums, or install with --allow-unverified",
347	+			errUnverifiedAsset, name, tag, asset, checksumsFileName)
348	+	}
349	+	return nil, fmt.Errorf("%w for %s/%s at %s %s", errAssetNotFound, runtime.GOOS, runtime.GOARCH, redactURL(repoURL), tag)
350	+}
351	+
352	+// assetNameFromURL derives the staging filename for a fully-specified
353	+// download_url. Only the URL path contributes: path.Base on the whole URL
354	+// folds a query string into the name ("entire-run.tar.gz?token=abc"), which
355	+// then misses extractPluginBinary's extension sniff and gets written out as
356	+// a raw binary — a silently broken install (and an invalid filename on
357	+// Windows).
358	+func assetNameFromURL(rawURL string) string {
359	+	if u, err := url.Parse(rawURL); err == nil && u.Path != "" {
360	+		return path.Base(u.Path)
361	+	}
362	+	trimmed := rawURL
363	+	if i := strings.IndexAny(trimmed, "?#"); i >= 0 {
364	+		trimmed = trimmed[:i]
365	+	}
366	+	return path.Base(trimmed)
367	+}
368	+
369	+// httpGetSmall fetches a small text resource (checksum manifests).
370	+func httpGetSmall(ctx context.Context, rawURL string) ([]byte, error) {
371	+	if err := requireSecureAssetURL(rawURL); err != nil {
372	+		return nil, err
373	+	}
374	+	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
375	+	if err != nil {
376	+		return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
377	+	}
378	+	resp, err := pluginHTTPClient.Do(req)
379	+	if err != nil {
380	+		return nil, fmt.Errorf("GET %s: %w", redactURL(rawURL), err)
381	+	}
382	+	defer resp.Body.Close()
383	+	if resp.StatusCode != http.StatusOK {
384	+		return nil, fmt.Errorf("GET %s: %s", redactURL(rawURL), resp.Status)
385	+	}
386	+	data, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
387	+	if err != nil {
388	+		return nil, fmt.Errorf("read %s: %w", redactURL(rawURL), err)
389	+	}
390	+	return data, nil
391	+}
392	+
393	+// fetchAndVerify downloads rawURL into stagingDir, streaming the SHA-256 as
394	+// it writes. A non-empty wantDigest is enforced; an empty one records the
395	+// computed digest. 404/410 map to errAssetNotFound. Partial files are
396	+// removed on verification failure so a hostile or truncated download never
397	+// lingers in staging.
398	+// Note on credentials: rawURL may carry userinfo, because releaseAssetBaseURL
399	+// derives the asset URL from the repo URL and url.String() re-serializes it.
400	+// The request keeps it — that is how the download authenticates to a private
401	+// forge — but every message below goes through redactURL, since main.go prints
402	+// command errors to stderr and a download failure is an ordinary event
403	+// (network hiccup, 5xx, checksum mismatch), not an exceptional one.
404	+func fetchAndVerify(ctx context.Context, rawURL, asset, wantDigest, stagingDir string) (*fetchedAsset, error) {
405	+	// The asset name is normally one of our own candidates, but the
406	+	// single-URL download_url template path derives it from the URL and a
407	+	// future caller could pass a name straight from a remote manifest.
408	+	// Refuse anything that wouldn't stay inside stagingDir. Backslash is
409	+	// rejected on every platform — it's a separator on Windows, and a
410	+	// literal backslash in an asset name is never legitimate.
411	+	if asset == "" || asset == "." || asset == ".." ||
412	+		strings.ContainsAny(asset, `/\`) || asset != filepath.Base(asset) {
413	+		return nil, fmt.Errorf("unsafe release asset name %q", asset)
414	+	}
415	+	if err := requireSecureAssetURL(rawURL); err != nil {
416	+		return nil, err
417	+	}
418	+	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
419	+	if err != nil {
420	+		return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
421	+	}
422	+	resp, err := pluginHTTPClient.Do(req)
423	+	if err != nil {
424	+		return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
425	+	}
426	+	defer resp.Body.Close()
427	+	switch resp.StatusCode {
428	+	case http.StatusOK:
429	+	case http.StatusNotFound, http.StatusGone:
430	+		return nil, fmt.Errorf("%w: GET %s: %s", errAssetNotFound, redactURL(rawURL), resp.Status)
431	+	default:
432	+		return nil, fmt.Errorf("download %s: %s", redactURL(rawURL), resp.Status)
433	+	}
434	+
435	+	dest := filepath.Join(stagingDir, asset)
436	+	out, err := os.Create(dest) //nolint:gosec // dest is inside the caller-owned staging dir; asset name came from our candidate list or checksum manifest
437	+	if err != nil {
438	+		return nil, fmt.Errorf("create staging file: %w", err)
439	+	}
440	+	h := sha256.New()
441	+	n, err := io.Copy(io.MultiWriter(out, h), io.LimitReader(resp.Body, maxPluginAssetSize+1))
442	+	closeErr := out.Close()
443	+	if err != nil {
444	+		_ = os.Remove(dest)
445	+		return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
446	+	}
447	+	if closeErr != nil {
448	+		_ = os.Remove(dest)
449	+		return nil, fmt.Errorf("write staging file: %w", closeErr)
450	+	}
451	+	if n > maxPluginAssetSize {
452	+		_ = os.Remove(dest)
453	+		return nil, fmt.Errorf("download %s: exceeds %d byte limit", redactURL(rawURL), int64(maxPluginAssetSize))
454	+	}
455	+	got := hex.EncodeToString(h.Sum(nil))
456	+	if wantDigest != "" && !strings.EqualFold(got, wantDigest) {
457	+		_ = os.Remove(dest)
458	+		return nil, fmt.Errorf("checksum mismatch for %s: got %s, want %s", asset, got, wantDigest)
459	+	}
460	+	return &fetchedAsset{Path: dest, Asset: asset, SHA256: got, Verified: wantDigest != ""}, nil
461	+}
462	+
463	+// extractPluginBinary locates the plugin executable inside the downloaded
464	+// asset and writes it to destPath (mode 0755 on Unix). Raw binaries are
465	+// copied; .tar.gz/.tgz and .zip archives are searched for an entry whose
466	+// basename matches entire-<name>[.exe], wherever it sits in the archive.
467	+func extractPluginBinary(assetPath, name, destPath string) error {
468	+	binName := pluginBinaryPrefix + name
469	+	lower := strings.ToLower(assetPath)
470	+	switch {
471	+	case strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz"):
472	+		return extractFromTarGz(assetPath, binName, destPath)
473	+	case strings.HasSuffix(lower, ".zip"):
474	+		return extractFromZip(assetPath, binName, destPath)
475	+	default:
476	+		src, err := os.Open(assetPath) //nolint:gosec // staging-dir file we just wrote
477	+		if err != nil {
478	+			return fmt.Errorf("open asset: %w", err)
479	+		}
480	+		defer src.Close()
481	+		return writeExecutable(src, destPath)
482	+	}
483	+}
484	+
485	+// matchesPluginBinary reports whether an archive entry basename is the
486	+// plugin binary, tolerating a Windows extension.
487	+func matchesPluginBinary(entryName, binName string) bool {
488	+	base := path.Base(filepath.ToSlash(entryName))
489	+	if base == binName {
490	+		return true
491	+	}
492	+	return runtime.GOOS == windowsGOOS && strings.EqualFold(base, binName+windowsExeExt)
493	+}
494	+
495	+// safeArchiveEntry rejects entry names that could escape an extraction
496	+// root. We only ever extract a single matched file to a fixed dest, so this
497	+// is defense in depth against a hostile archive masking as a plugin.
498	+func safeArchiveEntry(entryName string) bool {
499	+	clean := path.Clean(filepath.ToSlash(entryName))
500	+	return !strings.HasPrefix(clean, "../") && !path.IsAbs(clean) && !strings.Contains(entryName, "\x00")
501	+}
502	+
503	+func extractFromTarGz(archivePath, binName, destPath string) error {
504	+	f, err := os.Open(archivePath) //nolint:gosec // staging-dir file we just wrote
505	+	if err != nil {
506	+		return fmt.Errorf("open archive: %w", err)
507	+	}
508	+	defer f.Close()
509	+	gz, err := gzip.NewReader(f)
510	+	if err != nil {
511	+		return fmt.Errorf("open gzip: %w", err)
512	+	}
513	+	defer gz.Close()
514	+	tr := tar.NewReader(gz)
515	+	for {
516	+		hdr, err := tr.Next()
517	+		if errors.Is(err, io.EOF) {
518	+			break
519	+		}
520	+		if err != nil {
521	+			return fmt.Errorf("read tar: %w", err)
522	+		}
523	+		if hdr.Typeflag != tar.TypeReg || !safeArchiveEntry(hdr.Name) || !matchesPluginBinary(hdr.Name, binName) {
524	+			continue
525	+		}
526	+		return writeExecutable(tr, destPath)
527	+	}
528	+	return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
529	+}
530	+
531	+func extractFromZip(archivePath, binName, destPath string) error {
532	+	zr, err := zip.OpenReader(archivePath)
533	+	if err != nil {
534	+		return fmt.Errorf("open zip: %w", err)
535	+	}
536	+	defer zr.Close()
537	+	for _, f := range zr.File {
538	+		if f.FileInfo().IsDir() || !safeArchiveEntry(f.Name) || !matchesPluginBinary(f.Name, binName) {
539	+			continue
540	+		}
541	+		rc, err := f.Open()
542	+		if err != nil {
543	+			return fmt.Errorf("open zip entry: %w", err)
544	+		}
545	+		defer rc.Close()
546	+		return writeExecutable(rc, destPath)
547	+	}
548	+	return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
549	+}
550	+
551	+// fileSHA256 returns the hex SHA-256 of the file at path. Used to record the
552	+// installed binary's digest and to re-check it in `plugin doctor`.
553	+func fileSHA256(path string) (string, error) {
554	+	f, err := os.Open(path) //nolint:gosec // path is inside the managed plugin tree
555	+	if err != nil {
556	+		return "", fmt.Errorf("open %s: %w", filepath.Base(path), err)
557	+	}
558	+	defer f.Close()
559	+	h := sha256.New()
560	+	if _, err := io.Copy(h, f); err != nil {
561	+		return "", fmt.Errorf("read %s: %w", filepath.Base(path), err)
562	+	}
563	+	return hex.EncodeToString(h.Sum(nil)), nil
564	+}
565	+
566	+// writeExecutable writes r to destPath with the executable bit set, bounded by
567	+// maxPluginAssetSize. Explicit chmod (not inherited archive mode) because
568	+// zip-built and raw-binary releases routinely lose the bit — the #1
569	+// "downloaded plugin doesn't run" failure.
570	+func writeExecutable(r io.Reader, destPath string) error {
571	+	return writeExecutableLimited(r, destPath, maxPluginAssetSize)
572	+}
573	+
574	+// writeExecutableLimited is writeExecutable with an explicit cap, so the
575	+// oversize path is testable without materializing 512 MiB.
576	+//
577	+// The cap lives here rather than in each caller's io.LimitReader because a
578	+// bare LimitReader makes truncation invisible: io.Copy returns a nil error at
579	+// the limit, so an archive entry larger than the cap was silently truncated
580	+// and installed as the plugin binary with the install reporting success. Worse
581	+// since binary_sha256 landed — the digest is computed from the truncated bytes,
582	+// so `plugin doctor` would confirm the corrupt binary as intact. Reading one
583	+// byte past the cap makes the overflow detectable, mirroring fetchAndVerify.
584	+func writeExecutableLimited(r io.Reader, destPath string, limit int64) error {
585	+	// Write to a sibling temp file and rename into place. Two reasons, both
586	+	// load-bearing:
587	+	//
588	+	//  - O_CREATE without O_EXCL follows a symlink at destPath, so a symlink
589	+	//    planted at pkg/<name>/entire-<name> by an earlier malicious plugin
590	+	//    would redirect this write anywhere the user can write (~/.zshrc, a git
591	+	//    hook). Creating a fresh temp name and renaming cannot follow anything.
592	+	//  - Opening destPath with O_TRUNC destroys the working binary before the
593	+	//    new bytes are known-good, so an interrupted or failed copy left the
594	+	//    plugin broken. This path is the *normal* one whenever staging and the
595	+	//    managed dir are on different filesystems (a tmpfs /tmp), not an edge
596	+	//    case.
597	+	tmp, err := os.CreateTemp(filepath.Dir(destPath), ".tmp-"+filepath.Base(destPath)+"-*")
598	+	if err != nil {
599	+		return fmt.Errorf("create staging binary: %w", err)
600	+	}
601	+	tmpName := tmp.Name()
602	+	defer func() { _ = os.Remove(tmpName) }() // no-op once the rename succeeds
603	+
604	+	n, err := io.Copy(tmp, io.LimitReader(r, limit+1))
605	+	if err != nil {
606	+		_ = tmp.Close()
607	+		return fmt.Errorf("write binary: %w", err)
608	+	}
609	+	if err := tmp.Close(); err != nil {
610	+		return fmt.Errorf("close binary: %w", err)
611	+	}
612	+	if n > limit {
613	+		return fmt.Errorf("plugin binary exceeds the %d byte limit", limit)
614	+	}
615	+	// CreateTemp makes 0600; the dispatcher needs it executable.
616	+	if err := os.Chmod(tmpName, 0o755); err != nil { //nolint:gosec // a plugin binary must be executable
617	+		return fmt.Errorf("set executable bit: %w", err)
618	+	}
619	+	if err := os.Rename(tmpName, destPath); err != nil {
620	+		return fmt.Errorf("place binary: %w", err)
621	+	}
622	+	return nil
623	+}
624

