27	+// maxDepDepth bounds transitive resolution. Plugin graphs are shallow in
28	+// practice; the bound turns a metadata cycle that slips past the visited
29	+// set (e.g. two names aliasing one repo) into an error instead of a hang.
30	+const maxDepDepth = 10
31	+
32	+// DepAction is one planned dependency install or upgrade.
33	+type DepAction struct {
34	+	Name       string
35	+	RepoURL    string
36	+	MinVersion string
37	+	// Upgrade is true when the dependency is installed but below
38	+	// MinVersion; the action reinstalls at the latest tag.
39	+	Upgrade bool
40	+	// CurrentTag is the installed tag for upgrades.
41	+	CurrentTag string
42	+}
43	+
44	+// DepPlan is the result of resolving a plugin's transitive requirements.
45	+type DepPlan struct {
46	+	Actions []DepAction
47	+	// Warnings are non-blocking observations, e.g. a dependency satisfied
48	+	// from raw $PATH whose version cannot be verified.
49	+	Warnings []string
50	+}
51	+
52	+// PlanDependencyInstalls resolves the transitive requirements of rootReqs
53	+// into ordered install/upgrade actions. Missing dependencies must be
54	+// resolvable to a repo URL via the requirement itself or the index. The
55	+// visited set plus a depth bound make cycles an error path, not a hang.
56	+func PlanDependencyInstalls(ctx context.Context, rootReqs []PluginRequirement, idx *PluginIndex) (*DepPlan, error) {
57	+	plan := &DepPlan{}
58	+	// name -> strictest min_version considered so far, not a plain seen-set:
59	+	// see planDeps.
60	+	considered := map[string]string{}
61	+	if err := planDeps(ctx, rootReqs, idx, plan, considered, 0); err != nil {
62	+		return nil, err
63	+	}
64	+	return plan, nil
65	+}
66	+
67	+// stricterMinVersion reports whether a demands a higher minimum than b.
68	+// An empty string means "no minimum": nothing is stricter than it, and any
69	+// concrete minimum is stricter than it.
70	+func stricterMinVersion(a, b string) bool {
71	+	switch {
72	+	case a == "":
73	+		return false
74	+	case b == "":
75	+		return true
76	+	default:
77	+		return semver.Compare(canonicalSemver(a), canonicalSemver(b)) > 0
78	+	}
79	+}
80	+
81	+// upsertDepAction keeps one action per plugin name, replacing an earlier
82	+// entry when a stricter requirement supersedes it.
83	+func upsertDepAction(plan *DepPlan, action DepAction) {
84	+	for i := range plan.Actions {
85	+		if plan.Actions[i].Name == action.Name {
86	+			plan.Actions[i] = action
87	+			return
88	+		}
89	+	}
90	+	plan.Actions = append(plan.Actions, action)
91	+}
92	+
93	+// addDepWarning appends a warning unless it is already present. Re-visiting a
94	+// name under a stricter constraint can re-derive the same observation, and
95	+// printing it twice would just look like a bug.
96	+func addDepWarning(plan *DepPlan, warning string) {
97	+	if warning == "" || slices.Contains(plan.Warnings, warning) {
98	+		return
99	+	}
100	+	plan.Warnings = append(plan.Warnings, warning)
101	+}
102	+
103	+func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, considered map[string]string, depth int) error {
104	+	if depth > maxDepDepth {
105	+		return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
106	+	}
107	+	for _, req := range reqs {
108	+		// Keyed by name *and* gated on the strictest min_version seen so far,
109	+		// not a plain seen-set. In a diamond where two requirers demand
110	+		// different minimums of the same plugin (A needs C >= v1, B needs
111	+		// C >= v2), a name-only set skipped B's stricter constraint entirely:
112	+		// an installed C satisfying v1 produced no action and no warning, so
113	+		// the install completed leaving B running against a too-old C. Doctor
114	+		// caught it afterwards — it walks each manifest's requirements
115	+		// independently — but the install should plan the upgrade, not defer
116	+		// the discovery.
117	+		if prev, seen := considered[req.Name]; seen && !stricterMinVersion(req.MinVersion, prev) {
118	+			continue
119	+		}
120	+		// Past the guard this name is either new or strictly stricter than
121	+		// what was recorded, so this requirement's minimum is the one to keep.
122	+		considered[req.Name] = req.MinVersion
123	+
124	+		status, err := dependencySatisfied(req)
125	+		if err != nil {
126	+			return err
127	+		}
128	+		addDepWarning(plan, status.Warning)
129	+		if status.Satisfied {
130	+			// An already-satisfied managed dependency can itself have
131	+			// gaps (e.g. its own dep was removed with --force since
132	+			// install). Walk its recorded requirements — offline, from
133	+			// the manifest — so installing a parent repairs the whole
134	+			// chain instead of stopping at the first satisfied node.
135	+			// PATH/local-dev installs have no manifest; doctor covers
136	+			// those.
137	+			if status.Manifest != nil {
138	+				if err := planDeps(ctx, status.Manifest.Requires, idx, plan, considered, depth+1); err != nil {
139	+					return err
140	+				}
141	+			}
142	+			continue
143	+		}
144	+
145	+		action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
146	+		if m := status.Manifest; m != nil {
147	+			// Installed but below min_version: upgrade in place from its
148	+			// recorded repo.
149	+			action.Upgrade = true
150	+			action.CurrentTag = m.Tag
151	+			action.RepoURL = m.RepoURL
152	+		} else {
153	+			// Missing: resolve by name through the index, which is the only
154	+			// source. See PluginRequirement for why an author-supplied URL is
155	+			// not accepted here.
156	+			e := idx.Find(req.Name)
157	+			if e == nil {
158	+				return fmt.Errorf("dependency %q is not installed and is not in the plugin index; ask the plugin author to get it listed (try 'entire plugin search %s'), or install it yourself from its repository URL first", req.Name, req.Name)
159	+			}
160	+			action.RepoURL = e.RepoURL
161	+		}
162	+		upsertDepAction(plan, action)
