164	+		// Recurse into what the dependency itself requires, using metadata
165	+		// only — nothing is downloaded during planning. Inspection
166	+		// failures don't fail the plan (the install will surface hard
167	+		// errors itself), but they must not be silent either: a confirmed
168	+		// plan that quietly omitted nested dependencies would look
169	+		// complete while leaving gaps for doctor to find.
170	+		tag := ""
171	+		if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
172	+			tag = tags[0]
173	+		}
174	+		if tag == "" {
175	+			addDepWarning(plan, fmt.Sprintf("could not list tags for %q (%s); its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", req.Name, redactURL(action.RepoURL)))
