193	+// dependencySatisfied checks whether a requirement is already met, in
194	+// order: managed install with manifest (version-checkable) → managed entry
195	+// without manifest (local-dev, version unknown) → raw $PATH (version
196	+// unknown). Note `entire plugin <verb>` runs with the user's original PATH
197	+// (main.go restores it for built-ins), so LookPath here sees only
198	+// raw-PATH plugins — managed entries are checked explicitly first.
199	+// depStatus is what dependencySatisfied concluded about one requirement.
200	+type depStatus struct {
201	+	// Satisfied is true when nothing needs installing.
202	+	Satisfied bool
203	+	// Manifest is the dependency's install manifest, or nil for a local-dev
204	+	// install or a raw-$PATH binary. Returned rather than re-loaded by callers:
205	+	// every one of them needed it, so the file was being read three times per
206	+	// requirement.
207	+	Manifest *PluginManifest
208	+	// Warning is a non-blocking observation, e.g. a min_version that cannot be
209	+	// verified because the dependency came from $PATH.
210	+	Warning string
211	+}
212	+
213	+func dependencySatisfied(req PluginRequirement) (depStatus, error) {
214	+	m, err := LoadPluginManifest(req.Name)
215	+	if err != nil {
216	+		return depStatus{}, err
217	+	}
218	+	if m != nil {
219	+		satisfied := req.MinVersion == "" ||
220	+			semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0
221	+		// Not satisfied here means installed-but-too-old, which is the upgrade
222	+		// path in planDeps.
223	+		return depStatus{Satisfied: satisfied, Manifest: m}, nil
224	+	}
225	+	installed, err := FindInstalledPlugin(req.Name)
226	+	if err != nil {
227	+		return depStatus{}, err
228	+	}
229	+	if installed != nil {
230	+		return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "a local-dev install")}, nil
231	+	}
232	+	if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
233	+		return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "$PATH")}, nil
234	+	}
235	+	return depStatus{}, nil
236	+}
237	+
238	+func unverifiableVersionWarning(req PluginRequirement, source string) string {
239	+	if req.MinVersion == "" {
240	+		return ""
241	+	}
242	+	return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
243	+}
244	+
245	+// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
246	+// allowUnverified is inherited from the root install so a single
247	+// --allow-unverified covers the whole transitive set the user confirmed,
248	+// rather than failing partway through on the first dependency without
249	+// published checksums.
250	+func ExecuteDepPlan(ctx context.Context, plan *DepPlan, allowUnverified bool) error {
251	+	for _, a := range plan.Actions {
252	+		// The plan named this dependency and the user confirmed that name; an
253	+		// install landing under a different one would never satisfy the
254	+		// requirement, leaving doctor to report it missing forever.
255	+		if _, err := InstallPluginFromRepo(ctx, a.RepoURL, a.Name, RemoteInstallOptions{
256	+			Force: a.Upgrade, AllowUnverified: allowUnverified,
257	+		}); err != nil {
258	+			return fmt.Errorf("install dependency %q: %w", a.Name, err)
259	+		}
260	+	}
261	+	return nil
262	+}
263	+
264	+// DependentsOf returns the names of managed plugins whose manifests list
265	+// name as a requirement — the remove guard. Computed by scanning
266	+// pkg/*/manifest.yml; no extra state to maintain.
267	+func DependentsOf(name string) ([]string, error) {
268	+	manifests, err := ListPluginManifests()
269	+	if err != nil {
270	+		return nil, err
271	+	}
272	+	var out []string
273	+	for _, m := range manifests {
274	+		for _, req := range m.Requires {
275	+			if req.Name == name {
276	+				out = append(out, m.Name)
277	+				break
278	+			}
279	+		}
280	+	}
281	+	return out, nil
282	+}
283	+
284	+// PluginDoctorIssue is one problem found by RunPluginDoctor.
285	+type PluginDoctorIssue struct {
286	+	Plugin  string
287	+	Problem string
288	+	Fix     string
289	+}
290	+
291	+// RunPluginDoctor checks every managed plugin: bin entry present, dangling
292	+// local-dev symlinks, dependency presence and min_versions, and (macOS) a
293	+// quarantine attribute that would block execution.
294	+func RunPluginDoctor(ctx context.Context) ([]PluginDoctorIssue, error) {
295	+	var issues []PluginDoctorIssue
296	+
297	+	installed, err := ListInstalledPlugins()
298	+	if err != nil {
299	+		return nil, err
