309	+					Fix:     "rebuild the target or run: entire plugin remove " + p.Name,
310	+				})
311	+			}
312	+		}
313	+		if q := quarantinedPath(ctx, p.Path); q != "" {
314	+			issues = append(issues, PluginDoctorIssue{
315	+				Plugin:  p.Name,
316	+				Problem: "binary carries the macOS quarantine attribute; Gatekeeper will block it",
