328	+			issues = append(issues, PluginDoctorIssue{
329	+				Plugin:  m.Name,
330	+				Problem: "has an install manifest but no entry in the managed bin dir",
331	+				Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", redactURL(m.RepoURL)),
332	+			})
333	+		}
334	+		issues = append(issues, checkManagedBinaryIntegrity(m)...)
335	+		for _, req := range m.Requires {
336	+			status, err := dependencySatisfied(req)
337	+			if err != nil {
338	+				return nil, err
