1	diff --git a/cmd/entire/cli/plugin_install_remote.go b/cmd/entire/cli/plugin_install_remote.go
2	new file mode 100644
3	index 00000000..0a0937d1
4	--- /dev/null
5	+++ b/cmd/entire/cli/plugin_install_remote.go
6	@@ -0,0 +1,324 @@
7	+package cli
8	+
9	+import (
10	+	"context"
11	+	"crypto/rand"
12	+	"encoding/hex"
13	+	"errors"
14	+	"fmt"
15	+	"os"
16	+	"path/filepath"
17	+	"runtime"
18	+	"strings"
19	+	"time"
20	+
21	+	"golang.org/x/mod/semver"
22	+)
23	+
24	+// Remote install orchestration: resolve tag → fetch metadata → download +
25	+// verify + extract → place under pkg/<name>/ → link into bin/ → write
26	+// manifest. The bin/ link goes through the same InstallPluginFromPath used
27	+// by local-dev installs, so conflict handling, atomic replace, and the
28	+// Windows symlink fallbacks are shared, not duplicated.
29	+
30	+// maxTagFallbacks bounds how many tags we walk down when the newest tag has
31	+// no published assets (tag pushed, release not finished).
32	+const maxTagFallbacks = 3
33	+
34	+// RemoteInstallOptions configures InstallPluginFromRepo. It holds only genuine
35	+// options — the repository and the expected name are required arguments,
36	+// because a caller that omits either is making a decision, not accepting a
37	+// default.
38	+type RemoteInstallOptions struct {
39	+	// Pin, when non-empty, installs exactly this tag and marks the
40	+	// manifest pinned so upgrade skips it.
41	+	Pin string
42	+	// Force replaces an existing managed entry with the same name.
43	+	Force bool
44	+	// AllowUnverified permits installing a release that publishes no
45	+	// checksums.txt covering this platform. Off by default: downloading and
46	+	// executing an unauthenticated binary is the supply-chain risk the
47	+	// checksum path exists to remove, so it takes an explicit opt-in.
48	+	AllowUnverified bool
49	+}
50	+
51	+// RemoteInstallResult is what a successful remote install produced.
52	+type RemoteInstallResult struct {
53	+	Installed *InstalledPlugin
54	+	Manifest  *PluginManifest
55	+	Metadata  *PluginMetadata
56	+	// SkippedTags lists newer tags that were passed over for missing
57	+	// assets, newest first. Callers surface these as warnings.
58	+	SkippedTags []string
59	+}
60	+
61	+// InstallPluginFromRepo installs a plugin from a git repository URL.
62	+// Dependency resolution deliberately does not happen here — callers
63	+// (the install command) plan and confirm dependency installs first.
64	+// expectedName is the plugin name the caller has already committed to — the
65	+// index entry the user asked for, the requirement being satisfied, or the
66	+// plugin being upgraded. Pass "" only for a bare `install <url>`, where the
67	+// repository legitimately names itself; installRepoAtTag explains why a
68	+// mismatch is otherwise fatal.
69	+//
70	+// It is a required argument rather than an options field on purpose. As a
71	+// field it could be silently omitted, and omitting it reopens a no-prompt
72	+// name-substitution hole; as an argument, passing "" is a visible choice at
73	+// the call site.
74	+func InstallPluginFromRepo(ctx context.Context, repoURL, expectedName string, opts RemoteInstallOptions) (*RemoteInstallResult, error) {
75	+	repoURL = strings.TrimRight(repoURL, "/")
76	+
77	+	var tags []string
78	+	if opts.Pin != "" {
79	+		tags = []string{opts.Pin}
80	+	} else {
81	+		var err error
82	+		tags, err = listRemoteSemverTags(ctx, repoURL)
83	+		if err != nil {
84	+			return nil, err
85	+		}
