87	+			return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to install one (or a non-semver tag)", redactURL(repoURL))
88	+		}
89	+		if len(tags) > maxTagFallbacks {
90	+			tags = tags[:maxTagFallbacks]
91	+		}
92	+	}
93	+
94	+	var lastErr error
95	+	for i, tag := range tags {
96	+		res, err := installRepoAtTag(ctx, repoURL, expectedName, tag, opts)
97	+		if err == nil {
98	+			res.SkippedTags = tags[:i]
99	+			return res, nil
100	+		}
101	+		lastErr = err
102	+		if !errors.Is(err, errAssetNotFound) {
103	+			return nil, err
104	+		}
105	+	}
106	+	return nil, lastErr
107	+}
