186	+	}
187	+
188	+	installed, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: pkgBin, Force: true})
189	+	if err != nil {
190	+		return nil, err
191	+	}
192	+
193	+	manifest := &PluginManifest{
194	+		Name:         name,
195	+		RepoURL:      repoURL,
196	+		Tag:          tag,
197	+		Asset:        asset.Asset,
198	+		SHA256:       asset.SHA256,
199	+		BinarySHA256: binDigest,
200	+		Unverified:   !asset.Verified,
201	+		Pinned:       opts.Pin != "",
202	+		InstalledAt:  time.Now().UTC(),
203	+	}
204	+	if meta != nil {
