221	+	FromTag, ToTag string
222	+}
223	+
224	+// UpgradeInstalledPlugin re-resolves the newest tag for a remote-installed
225	+// plugin and reinstalls when it differs from the manifest's tag. Plugins
226	+// without a manifest (local-dev symlinks) are not upgradable.
227	+func UpgradeInstalledPlugin(ctx context.Context, name string) (*UpgradeOutcome, error) {
228	+	m, err := LoadPluginManifest(name)
229	+	if err != nil {
230	+		return nil, err
231	+	}
232	+	if m == nil {
233	+		return nil, fmt.Errorf("plugin %q has no install manifest (local-dev install?); reinstall it from its repository URL to make it upgradable", name)
234	+	}
235	+	if m.Pinned {
236	+		return &UpgradeOutcome{Name: name, Pinned: true}, nil
237	+	}
238	+	tags, err := listRemoteSemverTags(ctx, m.RepoURL)
239	+	if err != nil {
240	+		return nil, err
241	+	}
242	+	if len(tags) == 0 {
243	+		return nil, fmt.Errorf("%s has no stable semver tags; prereleases are skipped, so pass --pin <tag> to move to one", redactURL(m.RepoURL))
244	+	}
245	+	// Semver comparison, not string equality: "v0.2.0" and "0.2.0" are the
246	+	// same version, and a remote that re-tagged with the other spelling
247	+	// must not trigger a reinstall.
248	+	if semver.Compare(canonicalSemver(tags[0]), canonicalSemver(m.Tag)) <= 0 {
249	+		return &UpgradeOutcome{Name: name, UpToDate: true}, nil
250	+	}
251	+	// Inherit the install-time trust decision: a plugin the user knowingly
252	+	// installed unverified shouldn't start failing on upgrade, and one
253	+	// installed verified must not silently downgrade to unverified.
254	+	res, err := InstallPluginFromRepo(ctx, m.RepoURL, name, RemoteInstallOptions{
255	+		Force: true, AllowUnverified: m.Unverified,
256	+	})
257	+	if err != nil {
